import jwt from 'jsonwebtoken';
import { Request, Response, NextFunction } from 'express';
import { logger } from './logger';

const SECRET = process.env.JWT_SECRET || 'dev-secret';
const TOKEN_EXPIRY = process.env.TOKEN_EXPIRY || '7d';

export function signToken(userId: string, role: string): string {
  return jwt.sign({ sub: userId, role }, SECRET, { expiresIn: TOKEN_EXPIRY });
}

export function verifyToken(token: string): { sub: string; role: string } {
  return jwt.verify(token, SECRET) as { sub: string; role: string };
}

export function authMiddleware(req: Request, res: Response, next: NextFunction) {
  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  try {
    const payload = verifyToken(header.slice(7));
    (req as any).userId = payload.sub;
    (req as any).userRole = payload.role;
    logger.info('Auth OK', { userId: payload.sub });
    next();
  } catch (err) {
    logger.warn('Auth failed', { err });
    res.status(401).json({ error: 'Invalid token' });
  }
}
